<?php require __DIR__.'/header.php'; $images=json_decode($item['images'],true) ?: []; ?><main id="main" class="container page-space"><a class="text-link" href="<?= e(url('classifieds')) ?>">← All classifieds</a><div class="classified-detail"><article><div class="eyebrow"><?= e($item['category_name']) ?><?php if ($item['is_premium']): ?> · Premium<?php endif ?></div><h1><?= e($item['title']) ?></h1><div class="meta">⌖ <?= e($item['location']) ?> · Posted <?= e(date('d M Y',strtotime($item['created_at']))) ?></div><?php if ($images): ?><img class="classified-cover" src="<?= e(media_url($images[0])) ?>" alt="<?= e($item['title']) ?>"><div class="photo-gallery"><?php foreach (array_slice($images,1) as $image): ?><a href="<?= e(media_url($image)) ?>" target="_blank" rel="noopener"><img src="<?= e(media_url($image)) ?>" alt="Additional listing photo" loading="lazy"></a><?php endforeach ?></div><?php endif ?><h2>About this advertisement</h2><p class="preserve-lines"><?= e($item['description']) ?></p></article><aside><div class="panel contact-card"><span class="eyebrow">ASKING PRICE</span><p class="price"><?= $item['price']!==null ? 'LKR '.number_format((float)$item['price'],2) : 'Contact for price' ?></p><hr><h3><?= e($item['contact_name']) ?></h3><p class="muted">Advertiser</p><a class="button full" href="tel:<?= e(preg_replace('/[^+0-9]/','',$item['contact_phone'])) ?>"><?= e($item['contact_phone']) ?></a><a class="button secondary full" href="mailto:<?= e($item['contact_email']) ?>">Email advertiser ↗</a><form action="<?= e(url('classifieds/favorite/'.$item['id'])) ?>" method="post"><?= csrf() ?><button class="button secondary full"><?= $favorite ? '♥ Remove from saved' : '♡ Save advertisement' ?></button></form><small class="muted">Expires <?= e(date('d M Y',strtotime($item['expires_at']))) ?></small></div></aside></div></main><?php require __DIR__.'/footer.php'; ?>
